  assert.equal(satisfies(`0.${max}.1`, `^0.${max}.0`), true);
  assert.equal(satisfies(`${max}.1.0`, `^${max}.0.0`), true);
  assert.equal(satisfies(`0.${max}.1`, `~0.${max}.0`), true);
  assert.deepEqual(resolve({ a: { '0.3.0': {}, '0.2.9': {} } }, { a: '^0.2.3' }), { a: '0.2.9' });
});

