  const predicate = compileRange(' \t* >=1.2.3 <2.0.0\n');
  assert.equal(predicate(parse('1.2.3')), true);
  assert.equal(predicate(parse('1.2.2')), false);
  assert.equal(predicate(parse('2.0.0')), false);
  assert.equal(satisfies('1.2.3', '1.2.3 <=1.2.3 >=1.2.3'), true);
  assert.equal(satisfies('1.2.3', '>1.2.3'), false);
  assert.equal(satisfies('1.2.4', '>1.2.3'), true);
  assert.equal(satisfies('1.2.4', '<=1.2.3'), false);
  assert.equal(satisfies('1.2.4', '1.2.3'), false);
  for (const range of [null, 1, '', ' \n', '1', '1.2.x', '>= 1.2.3', '=1.2.3',
