test('missing packages and exhausted choices return null; empty roots return plain objects', () => {
  assert.equal(resolve({}, { missing: '*' }), null);
  assert.equal(resolve({ a: {} }, { a: '*' }), null);
  assert.equal(resolve({ a: { '1.0.0': { missing: '*' } } }, { a: '*' }), null);
  assert.deepEqual(resolve({ a: { '1.0.0': { missing: '*' } } }, {}), {});
});

test('only own enumerable keys participate, special names are safe, and inputs stay unchanged', () => {
  const deps = Object.assign(Object.create(null), { constructor: '*' });
  const versions = Object.freeze({ '1.0.0': Object.freeze(deps) });
  const registry = Object.create(null);
  registry.__proto__ = versions;
  registry.constructor = Object.freeze({ '1.0.0': Object.freeze({}) });
  Object.defineProperty(registry, 'hidden', { value: null });
  Object.freeze(registry);
  const root = Object.freeze(Object.assign(Object.create(null), { __proto__: '*' }));
  // Object literals give __proto__ special semantics; install it as an own key.
  const actualRoot = Object.create(null);
  actualRoot.__proto__ = '*';
  Object.freeze(actualRoot);
  assert.deepEqual(resolve(registry, actualRoot), JSON.parse('{"__proto__":"1.0.0","constructor":"1.0.0"}'));
  assert.equal(Object.getPrototypeOf(resolve(registry, actualRoot)), Object.prototype);
  assert.deepEqual(resolve(registry, root), {});
  assert.deepEqual(Object.keys(registry), ['__proto__', 'constructor']);
  assert.deepEqual(deps, Object.assign(Object.create(null), { constructor: '*' }));
});

test('all maps, versions, and ranges are validated even when unreachable', () => {
  for (const bad of [null, [], 1, new Date(), Object.create({ inherited: {} })]) {
    assert.throws(() => resolve(bad, {}), TypeError);
    assert.throws(() => resolve({}, bad), TypeError);
    assert.throws(() => resolve({ unused: bad }, {}), TypeError);
    assert.throws(() => resolve({ unused: { '1.0.0': bad } }, {}), TypeError);
  }
  assert.throws(() => resolve({ unused: { '01.0.0': {} } }, {}), TypeError);
  assert.throws(() => resolve({ unused: { '1.0.0': { missing: 'invalid' } } }, {}), TypeError);
  assert.throws(() => resolve({}, { missing: '' }), TypeError);
});

